#pragma once

#include <functional>
#include <memory>
#include <string>
#include <vector>

#include "components.hpp"

// Every component found in include/components/ (the list is generated by CMake).
struct ComponentInfo
{
    enum class Kind { State, Gate };

    std::string name;                                           // the file name, e.g. "rsi"
    Kind kind{Kind::State};
    Params defaults;
    std::function<std::size_t(const Params&)> warmupBars;
    std::function<std::shared_ptr<AnyState>(const Params&)> makeState;      // State components only
    std::function<std::shared_ptr<AnyGate>(const Params&)> makeGate;        // Gate components only
};

// Sorted by name.
const std::vector<ComponentInfo>& componentRegistry();
const ComponentInfo* findComponent(const std::string& name);
std::string componentNames();
